import { identity, navigation, schools, objectives, proposals, statuses, team, resources } from './content.js';
const $ = (selector, root=document) => root.querySelector(selector);
const $$ = (selector, root=document) => [...root.querySelectorAll(selector)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const route = document.body.dataset.page || 'inicio';
const schoolName = id => schools.find(s=>s.id===id)?.name || (id==='comun'?'FIAG en conjunto':'UNJBG');
const scopeName = v => v==='asamblea'?'Asamblea Universitaria':'Consejo de Facultad';
const gotoForm = p => `/participa/?tipo=comentario&propuesta=${encodeURIComponent(p.id)}`;
const symbol = `<span class="mark" aria-hidden="true"><span class="mark-core"></span><span class="mark-cut"></span></span>`;

function brand(light=false){return `<a class="brand ${light?'brand-light':''}" href="/" aria-label="AURA, ir al inicio">${identity.logoUrl?`<img class="official-logo" src="${esc(identity.logoUrl)}" alt="Logo AURA">`:symbol}<span class="brand-words"><strong>AURA<span class="brand-period">.</span></strong><small>FIAG / UNJBG</small></span></a>`;}
function header(){return `<a class="skip-link" href="#main">Saltar al contenido</a><header class="site-header" id="site-header"><div class="container header-inner">${brand()}<button class="nav-trigger" type="button" aria-label="Abrir menú" aria-expanded="false" aria-controls="primary-nav"><span></span><span></span></button><nav id="primary-nav" class="main-nav" aria-label="Navegación principal">${navigation.map(n=>`<a href="${n.href}" ${route===n.key?'aria-current="page"':''}>${esc(n.label)}</a>`).join('')}<a class="nav-primary" href="/participa/">Deja tu idea <span aria-hidden="true">↗</span></a></nav></div></header>`;}
function footer(){return `<footer class="site-footer"><div class="container"><div class="footer-top"><div class="footer-brand">${brand(true)}<p>${esc(identity.description)}</p></div><div class="footer-links"><div><span>Explora</span><a href="/propuestas/">Propuestas</a><a href="/fiag/">La FIAG</a><a href="/asamblea/">Asamblea</a><a href="/seguimiento/">Seguimiento</a></div><div><span>Conecta</span><a href="/participa/">Envía una idea</a><a href="/equipo/">Conoce al equipo</a><a href="/recursos/">Documentos</a>${identity.instagram?`<a href="${esc(identity.instagram)}" rel="noopener noreferrer" target="_blank">Instagram ↗</a>`:''}${identity.email?`<a href="mailto:${esc(identity.email)}">Correo</a>`:''}</div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} AURA. Sitio en desarrollo continuo.</span><span>${esc(identity.institutionalNotice)}</span><a href="/privacidad/">Privacidad</a></div></div></footer>`;}
function eyebrow(text, light=false){return `<span class="eyebrow ${light?'eyebrow-light':''}"><span class="eyebrow-dot"></span>${text}</span>`;}
function sectionIntro(kicker,title,desc,actions=''){return `<div class="section-heading"><div>${eyebrow(kicker)}<h2>${title}</h2></div><div class="section-heading-side"><p>${desc}</p>${actions}</div></div>`;}
function proposalCard(p, i=0){const photos={'talleres-arquitectura':'infraestructura','laboratorios-civil':'laboratorios','campo-geologia':'investigacion','talleres-artes':'bienestar','acuerdos-fiag':'transparencia'};const pic=photos[p.id];return `<article class="proposal-card ${pic?'has-illustration':''}" style="--card-delay:${i*55}ms">${pic?`<a class="proposal-card-image" href="/propuestas/?id=${encodeURIComponent(p.id)}"><img src="/assets/campana/${pic}-foto.webp" alt="Imagen ilustrativa de ${esc(p.title)}" loading="lazy" width="900" height="725"></a>`:''}<div class="proposal-top"><span class="card-number">${String(i+1).padStart(2,'0')}</span><span class="card-status"><span class="status-dot"></span>${esc(statuses[p.status].title)}</span></div><div class="card-label">${esc(p.scope==='asamblea'?'ASAMBLEA':schoolName(p.school))} <span>·</span> ${esc(p.area)}</div><h3><a href="/propuestas/?id=${encodeURIComponent(p.id)}">${esc(p.title)}</a></h3><p>${esc(p.summary)}</p><div class="proposal-bottom"><span>${esc(scopeName(p.scope))}</span><a aria-label="Ver propuesta: ${esc(p.title)}" href="/propuestas/?id=${encodeURIComponent(p.id)}"><span aria-hidden="true">↗</span></a></div></article>`;}
function schoolCard(s){return `<a class="school-card" href="/propuestas/?escuela=${s.id}"><div class="school-card-head"><span>${esc(s.index)} / ${esc(s.code)}</span><span aria-hidden="true" class="school-icon">${esc(s.icon)}</span></div><h3>${esc(s.name)}</h3><p>${esc(s.summary)}</p><span class="school-link">Ver temas <span aria-hidden="true">↗</span></span></a>`;}
function banner(kicker,title,text,button='Participar',href='/participa/'){return `<section class="banner-cta"><div class="container banner-inner"><div>${eyebrow(kicker,true)}<h2>${title}</h2><p>${text}</p></div><a class="btn btn-mint" href="${href}">${button}<span aria-hidden="true">↗</span></a><div class="banner-orbit" aria-hidden="true"><span></span><span></span><span></span></div></div></section>`;}
function home(){
const editorial = [
  {image:'infraestructura', id:'talleres-arquitectura', eyebrow:'01 / INFRAESTRUCTURA', title:'Espacios para crear y aprender', summary:'Talleres y espacios académicos: necesidades por identificar y canalizar.'},
  {image:'laboratorios', id:'laboratorios-civil', eyebrow:'02 / EQUIPAMIENTO', title:'Laboratorios que acompañen la formación', summary:'Una ruta para identificar equipos, mantenimiento y necesidades.'},
  {image:'transparencia', id:'acuerdos-fiag', eyebrow:'03 / REPRESENTACIÓN', title:'Acuerdos públicos, información clara', summary:'Acceso y explicación de acuerdos públicos del Consejo de Facultad.'},
  {image:'investigacion', id:'campo-geologia', eyebrow:'04 / EXPERIENCIA', title:'Más conexión entre aula y campo', summary:'Planificación y seguimiento de actividades formativas de campo.'},
  {image:'bienestar', id:'escucha-fiag', eyebrow:'05 / PARTICIPACIÓN', title:'Una facultad que escucha', summary:'Un espacio organizado para recoger aportes y necesidades estudiantiles.'},
  {image:'asamblea', id:'asamblea-transparencia', eyebrow:'06 / ASAMBLEA', title:'Una agenda de alcance universitario', summary:'Un apartado complementario para normativa y transparencia universitaria.'}
];
const schoolImgs={arquitectura:'infraestructura',civil:'laboratorios',geologica:'investigacion',artes:'bienestar'};
return `${header()}<main id="main" class="aura-v2-home">
<section class="v2-hero" aria-labelledby="main-headline">
  <div class="v2-hero-meta container"><span class="v2-meta-pill"><span class="v2-blink"></span> AURA / FIAG / UNJBG</span><span>CONSEJO DE FACULTAD · 2026</span></div>
  <div class="v2-hero-grid container">
    <div class="v2-hero-copy"><span class="v2-micro">REPRESENTACIÓN ESTUDIANTIL · AGENDA EN CONSTRUCCIÓN</span>
      <h1 id="main-headline"><span>LA FIAG</span><span>TIENE</span><span class="v2-highlight">VOZ<span class="v2-burst" aria-hidden="true">✳</span></span></h1>
      <p>Un espacio para conocer propuestas, comprender cómo funciona el Consejo de Facultad y compartir ideas para las cuatro escuelas profesionales.</p>
      <div class="v2-hero-ctas"><a class="v2-pill v2-pill-ink" href="/propuestas/">Explorar propuestas <span aria-hidden="true">↗</span></a><a class="v2-pill v2-pill-line" href="/participa/">Enviar mi idea <span aria-hidden="true">↗</span></a></div>
    </div>
    <div class="v2-hero-art"><div class="v2-photo-shell"><img src="/assets/campana/transparencia-foto.webp" alt="Ilustración editorial de estudiantes conversando en una mesa de trabajo" fetchpriority="high" width="900" height="725"></div><div class="v2-photo-ring" aria-hidden="true"></div><span class="v2-float-stamp">ESCUCHA<br>· PROPUESTA<br>· SEGUIMIENTO</span><span class="v2-photo-script" aria-hidden="true">ideas ↗</span></div>
  </div>
  <div class="v2-hero-foot container"><span>01 / EL CONSEJO DE FACULTAD PRIMERO</span><a href="#conoce">DESLIZA PARA EXPLORAR <span aria-hidden="true">↓</span></a></div>
</section>
<div class="v2-marquee" aria-hidden="true"><div class="v2-marquee-track">ESCUCHAR <span>✳</span> PROPONER <span>✳</span> INFORMAR <span>✳</span> PARTICIPAR <span>✳</span> ESCUCHAR <span>✳</span> PROPONER <span>✳</span> INFORMAR <span>✳</span> PARTICIPAR <span>✳</span></div></div>
<section id="conoce" class="v2-manifesto section"><div class="container v2-manifesto-layout"><div><span class="v2-tag">01 / QUIÉNES SOMOS</span><h2>UNA<br>FACULTAD<span class="v2-asterisk">*</span><br><em>CUATRO</em><br>REALIDADES.</h2></div><div class="v2-manifesto-aside"><span class="v2-drawn-star" aria-hidden="true">✳</span><p>La FIAG reúne carreras, experiencias y necesidades diferentes. Esta plataforma presenta a AURA, sus líneas de trabajo y una forma ordenada de recibir aportes estudiantiles.</p><a class="v2-underline-link" href="/conocenos/">Conoce AURA <span>↗</span></a><div class="v2-manifesto-note">Arquitectura · Ingeniería Civil<br>Ingeniería Geológica-Geotecnia · Artes</div></div></div></section>
<section class="v2-school-section section" id="escuelas"><div class="container"><div class="v2-heading-row"><div><span class="v2-tag">02 / TU ESCUELA IMPORTA</span><h2>¿QUÉ PASA<br>EN <em>TU ESCUELA?</em></h2></div><p>Cuatro espacios para conocer los temas propuestos y aportar experiencias propias. Cada escuela tiene una agenda abierta a revisión.</p></div><div class="v2-schools-list">${schools.map((s,i)=>`<a class="v2-school-line" href="/fiag/${schoolSlugV3(s.id)}/"><span class="v2-school-n">0${i+1}</span><span class="v2-school-title">${esc(s.name)}</span><span class="v2-school-code">${esc(s.code)}</span><span class="v2-school-thumb"><img src="/assets/campana/${schoolImgs[s.id]}-foto.webp" alt="" loading="lazy" width="900" height="725"></span><span class="v2-school-go" aria-hidden="true">↗</span></a>`).join('')}</div><div class="v2-schools-note"><span>UN MISMO ESPACIO DE REPRESENTACIÓN</span><a class="v2-underline-link" href="/fiag/">Conocer la FIAG ↗</a></div></div></section>
<section class="v2-features section" id="propuestas"><div class="container"><div class="v2-heading-row v2-heading-row-light"><div><span class="v2-tag">03 / CONSEJO DE FACULTAD</span><h2>IDEAS QUE<br><em>MERECEN</em> ESPACIO.</h2></div><div><p>Los temas son borradores abiertos a consulta. Cada ficha explica el problema, las acciones sugeridas y el órgano ante el que correspondería gestionar.</p><a class="v2-underline-link" href="/propuestas/">Todas las propuestas ↗</a></div></div><div class="v2-editorial-grid">${editorial.map((item,i)=>`<a class="v2-poster v2-poster-${i+1}" href="/propuestas/?id=${encodeURIComponent(item.id)}" aria-label="Abrir propuesta: ${esc(item.title)}"><div class="v2-poster-media"><img src="/assets/campana/${item.image}.webp" loading="lazy" alt="Diseño ilustrativo de ${esc(item.title)}" width="900" height="1125"></div><div class="v2-poster-caption"><span>${esc(item.eyebrow)}</span><h3>${esc(item.title)}</h3><span class="v2-open" aria-hidden="true">↗</span></div></a>`).join('')}</div><p class="v2-image-disclaimer">Imágenes de referencia creadas digitalmente. No representan fotografías reales de integrantes de AURA ni proyectos ejecutados.</p></div></section>
<section class="v2-process section"><div class="container"><div class="v2-process-lead"><span class="v2-tag">04 / DE LA IDEA A LA GESTIÓN</span><h2>PRIMERO<br><em>ESCUCHAMOS.</em><br>DESPUÉS<br>INFORMAMOS.</h2><a class="v2-pill v2-pill-ink" href="/seguimiento/">Cómo funciona el seguimiento <span aria-hidden="true">↗</span></a></div><div class="v2-process-steps">${[['01','Escuchar','Recoger aportes y conocer el contexto.'],['02','Sustentar','Contrastar datos, normativa y competencias.'],['03','Canalizar','Presentar asuntos ante las instancias correspondientes.'],['04','Informar','Distinguir las propuestas de las gestiones verificadas.']].map(s=>`<div class="v2-process-step"><span>${s[0]}</span><div><h3>${s[1]}</h3><p>${s[2]}</p></div><span aria-hidden="true">↗</span></div>`).join('')}</div></div></section>
<section class="v2-assembly"><div class="container v2-assembly-layout"><div class="v2-assembly-figure"><img src="/assets/campana/asamblea-foto.webp" alt="Ilustración editorial de una conversación entre universitarios" loading="lazy" width="900" height="725"><span>ÁMBITO UNIVERSITARIO ↗</span></div><div class="v2-assembly-copy"><span class="v2-tag">05 / SECCIÓN COMPLEMENTARIA</span><h2>Y ADEMÁS,<br><em>ASAMBLEA</em><br>UNIVERSITARIA.</h2><p>La prioridad aquí es el Consejo de Facultad FIAG. También reunimos temas de alcance universitario sobre normativa, organización y transparencia, en un espacio independiente.</p><a class="v2-pill v2-pill-ink" href="/asamblea/">Explorar Asamblea <span aria-hidden="true">↗</span></a></div></div></section>
<section class="v2-participa section"><div class="container v2-participa-layout"><div><span class="v2-tag">06 / PARTICIPA</span><h2>ESTE ESPACIO<br>TIENE LUGAR<br>PARA <em>TU IDEA.</em></h2><p>Comenta una propuesta, comparte una dificultad académica o plantea un tema que deba revisarse. No necesitas pertenecer al equipo.</p><a class="v2-pill v2-pill-mint" href="/participa/">Enviar comentario o sugerencia <span aria-hidden="true">↗</span></a></div><div class="v2-participa-art" aria-hidden="true"><div class="v2-circle-one"></div><div class="v2-circle-two"></div><span class="v2-participa-word">¡HABLEMOS!</span><span class="v2-participa-spark">✳</span></div></div></section>
<section class="v2-end-links section"><div class="container"><span class="v2-tag">07 / SIGUE EXPLORANDO</span><div class="v2-end-grid"><a href="/equipo/"><span>01</span>Conoce al equipo <span>↗</span></a><a href="/seguimiento/"><span>02</span>Seguimiento <span>↗</span></a><a href="/recursos/"><span>03</span>Normas y documentos <span>↗</span></a></div></div></section>
</main>${footer()}`;
}
function pageHero(kicker,title,summary,dark=false){return `<section class="page-hero ${dark?'page-hero-dark':''}"><div class="container page-hero-inner">${eyebrow(kicker,dark)}<h1>${title}</h1><p>${summary}</p></div></section>`;}
function proposalsListing(){return `${header()}<main id="main">${pageHero('AGENDA DE TRABAJO','Propuestas para <em>conversar y construir.</em>','El Consejo de Facultad concentra la agenda principal. Las iniciativas de Asamblea Universitaria se muestran por separado. Todos los temas permanecen en consulta hasta que el equipo los valide.')}
<section class="section filters-section"><div class="container"><div class="filter-heading"><h2>Explora las líneas de trabajo</h2><span id="count-proposals" aria-live="polite"></span></div><div class="filter-controls"><div class="segmented" role="group" aria-label="Ámbito de representación"><button type="button" class="filter-scope active" data-scope="fiag">Consejo FIAG</button><button type="button" class="filter-scope" data-scope="asamblea">Asamblea</button><button type="button" class="filter-scope" data-scope="todos">Todas</button></div><div class="filter-extra"><label class="sr-only" for="school-filter">Filtrar escuela</label><select id="school-filter"><option value="todos">Todas las escuelas</option>${schools.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}<option value="comun">FIAG en conjunto</option></select><label class="sr-only" for="search-proposals">Buscar propuestas</label><input type="search" id="search-proposals" placeholder="Buscar por tema…"></div></div><div id="proposal-list" class="proposal-grid" aria-live="polite"></div><p class="disclaimer">Las fichas describen temas para consulta. No representan acuerdos aprobados, compromisos definitivos ni acciones ya realizadas.</p></div></section>${banner('¿FALTA UN TEMA?','Ayúdanos a ampliar la agenda.','Envía tu propuesta o comparte un problema que deba documentarse.','Proponer un tema')}</main>${footer()}`;}
function proposalDetail(p){return `${header()}<main id="main"><section class="detail-intro"><div class="container"><a class="back-link" href="/propuestas/">← Todas las propuestas</a><div class="detail-metadata">${eyebrow(p.scope==='fiag'?'CONSEJO DE FACULTAD':'ASAMBLEA UNIVERSITARIA',true)}<span class="pill-subtle">${esc(statuses[p.status].title)}</span></div><h1>${esc(p.title)}</h1><p>${esc(p.summary)}</p><div class="detail-chips"><span>${esc(scopeName(p.scope))}</span><span>${esc(schoolName(p.school))}</span><span>${esc(p.area)}</span></div></div></section><section class="section detail-body"><div class="container detail-grid"><aside class="detail-sidebar"><span class="sidebar-heading">EN ESTA PROPUESTA</span><a href="#problema">01 / Contexto</a><a href="#acciones">02 / Acciones posibles</a><a href="#resultado">03 / Resultado esperado</a><a href="#competencia">04 / Alcance institucional</a><div class="detail-note"><span class="status-dot"></span><strong>${esc(statuses[p.status].title)}</strong><p>${esc(statuses[p.status].description)}</p></div></aside><article class="detail-article"><section id="problema"><span class="detail-counter">01</span><h2>¿Qué situación aborda?</h2><p>${esc(p.problem)}</p></section><section id="acciones"><span class="detail-counter">02</span><h2>Acciones para evaluar</h2><ol>${p.actions.map(a=>`<li>${esc(a)}</li>`).join('')}</ol></section><section id="resultado"><span class="detail-counter">03</span><h2>Resultado esperado</h2><p>${esc(p.result)}</p></section><section id="competencia"><span class="detail-counter">04</span><h2>¿Desde qué espacio se canaliza?</h2><p>${esc(p.competence)}</p><div class="notice-box">Este contenido está en consulta. La viabilidad depende del sustento y de decisiones de los órganos competentes.</div></section><div class="detail-feedback"><div><h3>¿Tienes un aporte sobre esta idea?</h3><p>Envía una observación vinculada a esta propuesta.</p></div><a class="btn btn-mint" href="${gotoForm(p)}">Comentar propuesta ↗</a></div></article></div></section></main>${footer()}`;}
function fiag(){return `${header()}<main id="main">${pageHero('NUESTRA FACULTAD','Cuatro escuelas, <em>una FIAG.</em>','La Facultad de Ingeniería Civil, Arquitectura y Geotecnia integra a Arquitectura, Ingeniería Civil, Ingeniería Geológica-Geotecnia y Artes. Cada escuela tiene demandas académicas propias.',true)}<section class="section"><div class="container">${sectionIntro('ESCUELAS PROFESIONALES','Conoce los temas por <em>escuela.</em>','Las líneas de trabajo son propuestas para ser revisadas con estudiantes y contrastadas con información institucional.')}<div class="school-grid">${schools.map(schoolCard).join('')}</div></div></section><section class="section fiag-explainer"><div class="container split-intro"><div>${eyebrow('COMPETENCIAS INSTITUCIONALES')}<h2>¿Qué es el Consejo de <em>Facultad?</em></h2></div><div><p>Es un órgano de gobierno de la facultad. Sus atribuciones están reguladas por la Ley Universitaria, el Estatuto y normas institucionales. La representación estudiantil participa dentro de ese marco, no reemplaza las funciones ejecutivas del Decanato o de otras dependencias.</p><p>Por eso cada propuesta señala qué se puede plantear, ante quién se debe gestionar y qué evidencia sirve para dar seguimiento.</p><a class="text-link" href="/recursos/">Consultar normativa y fuentes ↗</a></div></div></section><section class="section"><div class="container">${sectionIntro('TEMAS COMPARTIDOS','Lo que afecta a <em>toda la facultad.</em>','Las áreas y servicios comunes también necesitan atención.') }<div class="proposal-grid">${proposals.filter(p=>p.school==='comun').map(proposalCard).join('')}</div></div></section>${banner('TU ESCUELA','Cuéntanos qué pasa en tu facultad.','Envía información sobre situaciones que afecten la experiencia académica y propone alternativas.','Enviar sugerencia')}</main>${footer()}`;}
function about(){return `${header()}<main id="main">${pageHero('QUIÉNES SOMOS','AURA, un espacio de <em>representación.</em>','Un proyecto de participación estudiantil enfocado principalmente en el Consejo de Facultad de la FIAG, con propuestas complementarias relacionadas con la Asamblea Universitaria.',true)}<section class="section about-manifesto"><div class="container about-split"><div>${eyebrow('EL PROYECTO')}<h2>Ideas claras.<br><em>Canales abiertos.</em></h2></div><div><p class="large-paragraph">El propósito de este sitio es presentar una agenda en construcción, identificar el ámbito de cada iniciativa y ofrecer un canal para que estudiantes hagan llegar sus preocupaciones y sugerencias.</p><p>AURA todavía debe completar en esta versión su historia, la descripción oficial de su organización y la relación de integrantes. Estos datos se publicarán cuando el equipo los valide.</p></div></div></section><section class="section objectives-section"><div class="container">${sectionIntro('OBJETIVOS PARA DISCUSIÓN','Cuatro objetivos <em>propuestos.</em>','Estos ejes son una redacción de trabajo que deberá validar el equipo.') }<div class="objective-grid">${objectives.map(o=>`<article class="objective"><span>${o.n}</span><h3>${esc(o.title)}</h3><p>${esc(o.text)}</p></article>`).join('')}</div></div></section><section class="section"><div class="container">${sectionIntro('DOS ÁMBITOS','Una agenda con <em>responsabilidades distintas.</em>','El Consejo de Facultad es el eje central y Asamblea Universitaria tiene un apartado complementario.') }<div class="scope-grid"><a href="/propuestas/?ambito=fiag" class="scope-card primary-scope"><span>PRIORIDAD PRINCIPAL</span><h3>Consejo de Facultad FIAG</h3><p>Escuelas, asuntos académicos, infraestructura y propuestas ante instancias de facultad.</p><strong>Ver propuestas ↗</strong></a><a href="/asamblea/" class="scope-card"><span>ESPACIO COMPLEMENTARIO</span><h3>Asamblea Universitaria</h3><p>Organización universitaria, decisiones estatutarias y temas de alcance general.</p><strong>Conocer el apartado ↗</strong></a></div></div></section>${banner('PARTICIPA','La agenda se puede revisar.','Comparte ideas y observaciones para alimentar el diálogo.','Enviar mi aporte')}</main>${footer()}`;}
function assembly(){return `${header()}<main id="main">${pageHero('ESPACIO COMPLEMENTARIO','Propuestas de <em>Asamblea Universitaria.</em>','El eje principal del sitio es Consejo de Facultad FIAG. Este apartado reúne temas que requieren discusión desde una escala institucional más amplia.') }<section class="section"><div class="container"><div class="assembly-notice"><span class="notice-symbol">↗</span><p>Las atribuciones de Asamblea Universitaria son distintas a las del Consejo de Facultad. Cada iniciativa debe analizarse a la luz de la Ley Universitaria, el Estatuto y los procedimientos de la UNJBG.</p></div>${sectionIntro('ALCANCE UNIVERSITARIO','Iniciativas en <em>consulta.</em>','Ejemplos de líneas de trabajo que aún requieren revisión, sustento y validación.')}<div class="proposal-grid">${proposals.filter(p=>p.scope==='asamblea').map(proposalCard).join('')}</div></div></section>${banner('UNA MIRADA MÁS AMPLIA','¿Qué tema universitario te preocupa?','Aporta una idea relacionada con normativa, organización o información pública.','Enviar propuesta')}</main>${footer()}`;}
function teamPage(){const cards=team.length?team.map(t=>`<article class="team-card">${t.photo?`<img loading="lazy" src="${esc(t.photo)}" alt="Fotografía de ${esc(t.name)}">`:`<div class="team-initial">${esc(t.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</div>`}<div><span>${esc(t.role)} · ${esc(t.school)}</span><h3>${esc(t.name)}</h3><p>${esc(t.bio||'')}</p></div></article>`).join(''):`<div class="empty-state"><span class="empty-glyph">✳</span><h2>Presentaremos al equipo cuando su información esté validada.</h2><p>Los nombres, fotografías, escuelas y responsabilidades se incorporarán con autorización de cada integrante. No publicamos personas ficticias ni puestos sin confirmar.</p></div>`;return `${header()}<main id="main">${pageHero('LAS PERSONAS DETRÁS DEL PROYECTO','Conoce al <em>equipo AURA.</em>','Presentaremos a los integrantes y sus responsabilidades de forma clara y verificable.') }<section class="section"><div class="container"><div class="team-grid">${cards}</div></div></section>${banner('CONTACTO','¿Quieres conversar con el equipo?','Puedes enviar tu consulta mediante el canal de participación.','Ir a contacto')}</main>${footer()}`;}
function tracking(){return `${header()}<main id="main">${pageHero('TRANSPARENCIA','Seguimiento de <em>iniciativas.</em>','Diferenciamos las ideas abiertas a consulta de las gestiones efectivamente presentadas. Ninguna propuesta aparecerá como ejecutada sin respaldo documental.',true)}<section class="section"><div class="container">${sectionIntro('ETAPAS DE TRABAJO','Cómo se registra el <em>avance.</em>','Los estados se actualizan únicamente cuando existan hechos verificables.') }<div class="tracking-timeline">${Object.entries(statuses).map(([key,s],i)=>`<div class="tracking-step"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p></div></div>`).join('')}</div></div></section><section class="section section-track-data"><div class="container"><div class="track-note"><span class="notice-symbol">i</span><div><h3>Estado actual de la agenda</h3><p>Los ${proposals.length} temas de ejemplo están registrados como «En consulta». Todavía no hemos incorporado actas, solicitudes ni evidencias de gestiones realizadas por AURA.</p><a class="text-link" href="/propuestas/">Explorar temas ↗</a></div></div></div></section></main>${footer()}`;}
function resourcesPage(){return `${header()}<main id="main">${pageHero('FUENTES Y DOCUMENTOS','Información para <em>consultar.</em>','Reunimos enlaces institucionales y normas para contrastar el alcance de las propuestas. Las versiones vigentes deben verificarse siempre en sus fuentes oficiales.') }<section class="section"><div class="container"><div class="resource-grid">${resources.map((r,i)=>`<a class="resource-card" href="${esc(r.href)}" target="_blank" rel="noopener noreferrer"><span class="resource-number">${String(i+1).padStart(2,'0')}</span><span class="resource-type">${esc(r.type)}</span><h3>${esc(r.title)}</h3><p>${esc(r.detail)}</p><span class="resource-arrow">↗</span></a>`).join('')}</div><div class="resource-placeholder"><h2>Plan de trabajo y documentos de AURA</h2><p>El plan aprobado, presentaciones y documentos propios se podrán agregar aquí cuando el equipo entregue sus versiones finales y autorice su publicación.</p></div></div></section></main>${footer()}`;}
function formPage(){const params=new URLSearchParams(location.search), proposal=proposals.find(p=>p.id===params.get('propuesta')), type=params.get('tipo')||'idea';return `${header()}<main id="main">${pageHero('ESCUCHA ESTUDIANTIL','Tu voz tiene <em>un espacio.</em>','Envía una sugerencia, plantea un problema o comenta una propuesta. No necesitas pertenecer a AURA para comunicarte.') }<section class="section participatory-section"><div class="container participation-layout"><aside class="participation-aside">${eyebrow('ANTES DE ENVIAR')}<h2>Una conversación empieza con <em>un mensaje.</em></h2><p>Tu aporte se revisa de manera privada. El equipo podrá clasificarlo y utilizar datos generales no identificables para orientar su agenda.</p><div class="participation-points"><div><span>01</span><p>Describe una situación o propuesta con claridad.</p></div><div><span>02</span><p>Elige tu escuela si corresponde.</p></div><div><span>03</span><p>Deja un correo únicamente si deseas recibir una respuesta.</p></div></div><div class="privacy-aside">No es una mesa de partes de la UNJBG, ni sustituye los canales oficiales para emergencias, denuncias formales o trámites.</div></aside><div class="form-shell"><div class="form-head"><span>FORMULARIO / AURA</span><span id="form-status" role="status" class="form-status">Comprobando disponibilidad…</span></div>${proposal?`<div class="linked-proposal"><span>COMENTARIO VINCULADO A</span><strong>${esc(proposal.title)}</strong></div>`:''}<form id="idea-form" novalidate><div class="field"><label for="type">¿Qué deseas compartir? <span>*</span></label><select id="type" name="type" required><option value="idea" ${type==='idea'?'selected':''}>Una idea o propuesta</option><option value="problema" ${type==='problema'?'selected':''}>Un problema o necesidad</option><option value="comentario" ${type==='comentario'?'selected':''}>Un comentario u observación</option><option value="contacto" ${type==='contacto'?'selected':''}>Una consulta para el equipo</option></select></div><div class="field"><label for="school">Escuela profesional <span>*</span></label><select id="school" name="school" required><option value="">Selecciona tu escuela</option>${schools.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}<option value="otra">Otra escuela / facultad</option><option value="prefiero-no-decir">Prefiero no indicar</option></select></div><div class="field"><label for="subject">Asunto <span>*</span></label><input id="subject" name="subject" type="text" minlength="5" maxlength="110" autocomplete="off" placeholder="Ej. Acceso al taller de mi escuela" required></div><div class="field"><label for="message">Cuéntanos tu idea <span>*</span></label><textarea id="message" name="message" rows="6" minlength="20" maxlength="3000" placeholder="Describe la situación, cómo afecta a estudiantes y qué solución propones…" required></textarea><small>Entre 20 y 3 000 caracteres. Evita incluir datos sensibles de otras personas.</small></div><div class="form-divider"><span>OPCIONAL · SI DESEAS RESPUESTA</span></div><div class="field-row"><div class="field"><label for="senderName">Tu nombre</label><input id="senderName" name="senderName" type="text" maxlength="80" autocomplete="name" placeholder="Nombre (opcional)"></div><div class="field"><label for="email">Tu correo</label><input id="email" name="email" type="email" maxlength="120" autocomplete="email" placeholder="correo@ejemplo.com"></div></div><div class="honey" aria-hidden="true"><label for="website">No llenar este campo</label><input type="text" id="website" name="website" tabindex="-1" autocomplete="off"></div><label class="consent-label"><input id="consent" type="checkbox" required><span>He leído el <a href="/privacidad/" target="_blank" rel="noopener">aviso de privacidad</a> y autorizo el tratamiento de los datos que envío para gestionar mi mensaje. <strong>*</strong></span></label><div class="form-response" role="alert" id="form-response" hidden></div><div class="form-actions"><button class="btn btn-dark" type="submit" id="form-submit" disabled>Enviar mensaje <span aria-hidden="true">↗</span></button><p>Los campos marcados con * son obligatorios.</p></div></form></div></div></section></main>${footer()}`;}
function privacy(){return `${header()}<main id="main">${pageHero('TRATAMIENTO DE INFORMACIÓN','Aviso de <em>privacidad.</em>','Información básica sobre el buzón de participación AURA. Debe ser revisada y completada por el responsable antes de activar formularios públicos.') }<section class="section"><div class="container legal-page"><div class="notice-box"><strong>Documento de trabajo:</strong> antes de habilitar la captación de datos, AURA debe completar el nombre y contacto del responsable del tratamiento, el periodo de conservación y el procedimiento de ejercicio de derechos. No publicar como definitivo sin esa revisión.</div><h2>Finalidad del formulario</h2><p>Los datos enviados se usan para registrar y revisar propuestas, comentarios, necesidades y solicitudes de contacto relacionadas con la actividad estudiantil de AURA.</p><h2>Información solicitada</h2><p>Tipo de mensaje, escuela, asunto y descripción. Nombre y correo son opcionales. No se solicita DNI ni código universitario. Evita enviar información médica, denuncias identificables u otros datos sensibles.</p><h2>Acceso y conservación</h2><p>La información se almacena en un servicio privado de Azure, cuando se configura, y está destinada al equipo autorizado. Antes del lanzamiento oficial se debe definir y publicar un plazo de conservación, responsables de acceso y un procedimiento de eliminación.</p><h2>Uso y difusión</h2><p>Los mensajes individuales no se publican automáticamente. Las estadísticas o resúmenes públicos, si se crean, deben excluir información que identifique a remitentes. No se utilizarán correos para campañas de mensajes sin consentimiento separado.</p><h2>Derechos y contacto</h2><p>El responsable deberá habilitar un correo verificable para solicitar acceso, rectificación u otras medidas que correspondan conforme a la legislación peruana de datos personales.</p><p>${esc(identity.institutionalNotice)}</p></div></section></main>${footer()}`;}
async function statusForm(){const status=$('#form-status'),button=$('#form-submit'); if(!status)return;try{const req=await fetch('/api/status',{headers:{'Accept':'application/json'},cache:'no-store'});const data=await req.json(); if(req.ok&&data.ready){status.textContent='Buzón disponible';status.classList.add('ready');button.disabled=false;}else{status.textContent='Buzón pendiente de activación';setFormResponse('El formulario está preparado, pero todavía falta conectar el almacenamiento privado en Azure. Por ahora no recibimos mensajes.',true);}}catch{status.textContent='Buzón sin conexión';setFormResponse('No hay conexión con el servidor de mensajes. Puedes revisar las propuestas, pero todavía no es posible enviar el formulario.',true);}}
function setFormResponse(msg,error){const el=$('#form-response');if(!el)return;el.hidden=false;el.classList.toggle('error',error);el.textContent=msg;}
function wireForm(){const form=$('#idea-form');if(!form)return;statusForm();form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const btn=$('#form-submit');btn.disabled=true;const old=btn.innerHTML;btn.textContent='Enviando…';const fd=new FormData(form);const body={type:fd.get('type'),school:fd.get('school'),subject:fd.get('subject'),message:fd.get('message'),senderName:fd.get('senderName'),email:fd.get('email'),website:fd.get('website'),proposal:new URLSearchParams(location.search).get('propuesta')||'',consent:$('#consent').checked};try{const r=await fetch('/api/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo enviar tu mensaje.');form.reset();setFormResponse(`Mensaje recibido. Código de referencia: ${d.reference}. Consérvalo si necesitas dar seguimiento.`,false);$('#form-response').scrollIntoView({behavior:'smooth',block:'center'});}catch(err){setFormResponse(err.message||'Ocurrió un error al enviar.',true);}finally{btn.disabled=false;btn.innerHTML=old;}});}
function wireFilters(){const target=$('#proposal-list');if(!target)return;const params=new URLSearchParams(location.search);let scope=params.get('ambito')||'fiag';let school=params.get('escuela')||'todos';let search='';if(school!=='todos'&&scope==='asamblea')scope='fiag';if($('#school-filter'))$('#school-filter').value=school;const repaint=()=>{ $$('.filter-scope').forEach(b=>b.classList.toggle('active',b.dataset.scope===scope));const filtered=proposals.filter(p=>(scope==='todos'||p.scope===scope)&&(school==='todos'||p.school===school)&&(p.title+' '+p.summary+' '+p.area+' '+schoolName(p.school)).toLowerCase().includes(search));target.innerHTML=filtered.length?filtered.map(proposalCard).join(''):`<div class="no-results"><h3>Sin resultados para esos filtros.</h3><p>Prueba otra búsqueda o consulta las demás escuelas.</p></div>`;$('#count-proposals').textContent=`${filtered.length} ${filtered.length===1?'tema':'temas'}`;$('#school-filter').disabled=scope==='asamblea';};$$('.filter-scope').forEach(b=>b.addEventListener('click',()=>{scope=b.dataset.scope;if(scope==='asamblea')school='todos';$('#school-filter').value=school;repaint();}));$('#school-filter').addEventListener('change',e=>{school=e.target.value;repaint();});$('#search-proposals').addEventListener('input',e=>{search=e.target.value.trim().toLowerCase();repaint();});repaint();}
function wireNav(){const t=$('.nav-trigger'),nav=$('#primary-nav');if(!t)return;t.addEventListener('click',()=>{const open=nav.classList.toggle('nav-open');t.setAttribute('aria-expanded',String(open));t.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');document.body.classList.toggle('nav-is-open',open);});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('nav-open');t.setAttribute('aria-expanded','false');document.body.classList.remove('nav-is-open');}});}
async function adminPage(){return `${header()}<main id="main">${pageHero('SOLO PERSONAL AUTORIZADO','Bandeja de <em>participación.</em>','Revisión privada de mensajes recibidos. No publicar datos de estudiantes sin autorización.',true)}<section class="section"><div class="container"><div id="admin-root"><p>Comprobando acceso…</p></div></div></section></main>${footer()}`;}
const labels={idea:'Idea',problema:'Problema',comentario:'Comentario',contacto:'Consulta'};
async function wireAdmin(){const root=$('#admin-root');if(!root)return;try{const auth=await fetch('/.auth/me');const json=await auth.json();const user=(json.clientPrincipal)||null;if(!user||!user.userRoles?.includes('administrator')){root.innerHTML=`<div class="empty-state"><h2>Acceso para administradores</h2><p>Necesitas iniciar sesión con una cuenta invitada al rol administrator desde Azure.</p><a class="btn btn-dark" href="/.auth/login/github?post_login_redirect_uri=/admin/">Acceder con GitHub ↗</a></div>`;return;}const r=await fetch('/api/admin/messages',{cache:'no-store'});if(!r.ok)throw new Error('No se pudo consultar la bandeja.');const data=await r.json();const records=(data.items||[]).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));let filter='todos';root.innerHTML=`<div class="admin-tools"><div><h2>Mensajes recibidos <span class="admin-count">${records.length}</span></h2><p>${esc(user.userDetails||'Administrador')} · <a href="/.auth/logout?post_logout_redirect_uri=/">Cerrar sesión</a></p></div><div class="admin-tools-actions"><label class="sr-only" for="admin-filter">Filtrar estado</label><select id="admin-filter"><option value="todos">Todos los estados</option><option value="nuevo">Nuevo</option><option value="revision">En revisión</option><option value="respondido">Respondido</option><option value="cerrado">Cerrado</option></select><button class="btn btn-outline" id="admin-export">Exportar CSV</button></div></div><div id="admin-list" class="admin-list"></div><p class="admin-footnote">Vista de los mensajes más recientes (máximo 300 por carga). Los datos se almacenan de forma privada en Azure Table Storage.</p>`;
const repaint=()=>{$('#admin-list').innerHTML=records.filter(m=>filter==='todos'||m.status===filter).map(m=>`<article class="admin-item" data-id="${esc(m.id)}"><div class="admin-item-head"><div><span class="card-label">${esc(labels[m.type]||m.type)} · ${esc(schoolName(m.school))} · ${esc(new Date(m.createdAt).toLocaleString('es-PE'))}</span><h3>${esc(m.subject)}</h3></div><span class="pill-subtle">${esc(m.status)}</span></div><p class="admin-message">${esc(m.message)}</p><p class="admin-person">${m.senderName?`Nombre: ${esc(m.senderName)} · `:''}${m.email?`Correo: <a href="mailto:${esc(m.email)}">${esc(m.email)}</a> · `:''}Ref. ${esc(m.id)}</p><div class="admin-item-actions"><label>Estado <select data-action="status"><option value="nuevo" ${m.status==='nuevo'?'selected':''}>Nuevo</option><option value="revision" ${m.status==='revision'?'selected':''}>En revisión</option><option value="respondido" ${m.status==='respondido'?'selected':''}>Respondido</option><option value="cerrado" ${m.status==='cerrado'?'selected':''}>Cerrado</option></select></label><label>Nota interna <input type="text" data-action="note" maxlength="300" value="${esc(m.note||'')}" placeholder="Nota privada"></label><button type="button" class="btn btn-dark btn-small" data-action="save">Guardar</button><button type="button" class="btn btn-outline btn-small" data-action="delete">Eliminar</button></div><p class="admin-feedback" role="status"></p></article>`).join('')||'<p class="no-results">No hay mensajes con este estado.</p>';};repaint();$('#admin-filter').addEventListener('change',e=>{filter=e.target.value;repaint();});$('#admin-list').addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b)return;const box=b.closest('.admin-item'),id=box.dataset.id,msg=records.find(m=>m.id===id);if(!msg)return;const action=b.dataset.action;if(action==='delete'&&!confirm('¿Eliminar definitivamente este mensaje del almacenamiento?'))return;b.disabled=true;$('.admin-feedback',box).textContent='Procesando…';try{const payload={status:$('[data-action=status]',box).value,note:$('[data-action=note]',box).value};const r=await fetch(`/api/admin/messages/${encodeURIComponent(id)}`,{method:action==='delete'?'DELETE':'PATCH',headers:{'Content-Type':'application/json'},body:action==='delete'?undefined:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Error al guardar');if(action==='delete'){records.splice(records.indexOf(msg),1);repaint();}else{msg.status=payload.status;msg.note=payload.note;$('.admin-feedback',box).textContent='Cambios guardados.';$('.pill-subtle',box).textContent=payload.status;}}catch(err){$('.admin-feedback',box).textContent=err.message;}finally{b.disabled=false;}});$('#admin-export').addEventListener('click',()=>{const rows=[['ID','Fecha','Tipo','Escuela','Asunto','Mensaje','Nombre','Correo','Estado','Nota'],...records.map(m=>[m.id,m.createdAt,m.type,m.school,m.subject,m.message,m.senderName||'',m.email||'',m.status,m.note||''])];const text=rows.map(r=>r.map(c=>'"'+String(c).replace(/^([=+\-@\t\r])/,'\' $1').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='aura-mensajes.csv';a.click();URL.revokeObjectURL(url);});}catch(err){root.innerHTML=`<div class="notice-box">${esc(err.message||'No fue posible cargar la bandeja.')} Revisa la configuración del almacenamiento y el acceso administrator.</div>`;}}
function schoolSlugV3(id){return id==='geologica'?'geologica-geotecnia':id;}

function schoolTileV3(s,i){return `<a class="v3-school-tile" href="/fiag/${schoolSlugV3(s.id)}/"><span class="v3-tile-index">0${i+1} / ${esc(s.code)}</span><span class="v3-tile-title">${esc(s.name)}</span><span class="v3-tile-summary">${esc(s.summary)}</span><span class="v3-tile-arrow" aria-hidden="true">↗</span></a>`;}

function fiagV3(){return `${header()}<main id="main">${pageHero('NUESTRA FIAG','CUATRO ESCUELAS.<br><em>CUATRO HISTORIAS.</em>','Conoce qué caracteriza la experiencia académica de cada escuela y después explora sus temas de representación.',true)}
<section class="section v3-fiag-overview"><div class="container"><div class="v3-section-lead"><div>${eyebrow('01 / ELIGE TU ESCUELA')}<h2>PRIMERO CONOCE.<br><em>DESPUÉS PROPÓN.</em></h2></div><p>Cada escuela tiene su propio perfil: experiencias académicas, temas que escuchar y enlaces directos para participar. Las propuestas están en una sección distinta.</p></div><div class="v3-school-directory">${schools.map(schoolTileV3).join('')}</div></div></section>
<section class="section fiag-explainer"><div class="container split-intro"><div>${eyebrow('02 / REPRESENTACIÓN')}<h2>¿Qué hace el <em>Consejo de Facultad?</em></h2></div><div><p>Es un órgano de gobierno de la facultad. Las atribuciones se rigen por normas universitarias; la representación estudiantil no sustituye la gestión ejecutiva de las dependencias.</p><p>Las propuestas deben identificar competencia, evidencia y ruta de seguimiento.</p><a class="text-link" href="/recursos/">Consultar normativa y fuentes ↗</a></div></div></section>
<section class="v3-next-step section"><div class="container"><h2>¿YA CONOCES TU ESCUELA?</h2><p>Ahora descubre las ideas de trabajo o cuéntanos qué necesita mejorar.</p><div class="v3-actions"><a class="btn btn-dark" href="/propuestas/">Explorar propuestas ↗</a><a class="btn btn-mint" href="/participa/#formulario">Compartir una necesidad ↓</a></div></div></section></main>${footer()}`;}

function schoolProfileV3(){const id=document.body.dataset.school;const s=schools.find(x=>x.id===id);if(!s)return `${header()}<main id="main"><section class="section"><div class="container"><h1>Escuela no encontrada</h1><a href="/fiag/">Volver a Nuestra FIAG ↗</a></div></section></main>${footer()}`;const info={
 arquitectura:{headline:'DIBUJAR EL FUTURO.',intro:'El trabajo proyectual combina dibujo, diseño, elaboración de modelos y reflexión sobre los espacios.',context:'Talleres, herramientas de representación y actividades académicas marcan parte de la experiencia que queremos escuchar.',themes:['Disponibilidad y condiciones de talleres','Recursos gráficos y digitales','Visitas y experiencias de aprendizaje']},
 civil:{headline:'CONSTRUIR CON CRITERIO.',intro:'La formación en Ingeniería Civil articula fundamentos técnicos con ensayos, medición y resolución de problemas.',context:'Laboratorios, equipos de topografía y oportunidades de prácticas son temas que merecen diálogo documentado.',themes:['Laboratorios y materiales','Equipos de topografía','Prácticas y oportunidades formativas']},
 geologica:{headline:'ENTENDER EL TERRITORIO.',intro:'La formación geológica y geotécnica conecta observación, análisis de materiales y estudio del entorno.',context:'El trabajo de campo, la seguridad y la disponibilidad de instrumentos requieren planificación y conversación con la escuela.',themes:['Actividades de campo','Instrumentos y laboratorios','Investigación aplicada']},
 artes:{headline:'CREAR, EXPONER, COMPARTIR.',intro:'Los lenguajes artísticos se desarrollan mediante creación, experimentación y presentación de trabajos.',context:'Espacios, materiales, condiciones de taller y exhibiciones merecen escuchar a quienes los utilizan.',themes:['Talleres y materiales','Espacios para exhibir','Difusión de proyectos artísticos']}
}[s.id];const topics=proposals.filter(p=>p.school===s.id);return `${header()}<main id="main"><section class="v3-school-hero"><div class="container"><a class="v3-back" href="/fiag/">← Todas las escuelas</a><span class="v3-kicker">${esc(s.code)} / FIAG / UNJBG</span><h1>${esc(s.name)}</h1><p>${esc(info.headline)}</p><div class="v3-actions"><a class="btn btn-mint" href="/propuestas/?escuela=${encodeURIComponent(s.id)}">Ver propuestas de la escuela ↗</a><a class="btn btn-outline" href="/participa/?escuela=${encodeURIComponent(s.id)}#formulario">Contar mi experiencia ↓</a></div></div></section>
<section class="section v3-school-info"><div class="container v3-school-info-grid"><div>${eyebrow('01 / UNA MIRADA A LA ESCUELA')}<h2>${esc(info.headline)}</h2></div><div><p class="v3-big-copy">${esc(info.intro)}</p><p>${esc(info.context)}</p><p class="v3-small-note">Esta es una descripción informativa general, no un catálogo oficial de servicios activos ni un diagnóstico aprobado por la escuela.</p></div></div></section>
<section class="section v3-school-themes"><div class="container">${eyebrow('02 / TEMAS PARA ESCUCHAR')}<h2>LO QUE IMPORTA<br><em>EN TU FORMACIÓN.</em></h2><ol class="v3-theme-list">${info.themes.map((t,i)=>`<li><span>0${i+1}</span><strong>${esc(t)}</strong></li>`).join('')}</ol><p>Estas líneas están abiertas a consulta; no equivalen a proyectos ejecutados.</p></div></section>
<section class="section v3-school-related"><div class="container">${eyebrow('03 / IDEAS VINCULADAS')}<h2>PROPUESTAS DE<br><em>${esc(s.short)}.</em></h2><div class="v3-related-list">${topics.map((p,i)=>`<a href="/propuestas/?id=${encodeURIComponent(p.id)}"><span>0${i+1}</span><strong>${esc(p.title)}</strong><span aria-hidden="true">↗</span></a>`).join('')}</div><div class="v3-actions"><a class="btn btn-dark" href="/propuestas/?escuela=${encodeURIComponent(s.id)}">Abrir catálogo filtrado ↗</a><a class="btn btn-mint" href="/participa/?escuela=${encodeURIComponent(s.id)}#formulario">Participar ↓</a></div></div></section></main>${footer()}`;}

function proposalPanelV3(p,i){const photos={'talleres-arquitectura':'infraestructura','laboratorios-civil':'laboratorios','campo-geologia':'investigacion','talleres-artes':'bienestar','acuerdos-fiag':'transparencia'};const picture=p.image||photos[p.id]||null;return `<article class="v3-proposal-slide ${picture?'has-photo':'is-typographic'}" role="group" aria-roledescription="diapositiva" aria-label="Propuesta ${i+1}: ${esc(p.title)}"><div class="v3-proposal-media">${picture?`<img src="/assets/campana/${esc(picture)}-foto.webp" alt="" loading="lazy" width="900" height="725">`:`<span class="v3-proposal-watermark" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span class="v3-proposal-glyph" aria-hidden="true">✳</span>`}</div><div class="v3-proposal-info"><span class="v3-kicker">${esc(p.scope==='asamblea'?'ASAMBLEA':schoolName(p.school))} / ${esc(p.area)}</span><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p><span class="v3-proposal-status">${esc(statuses[p.status]?.title||'En consulta')}</span><div class="v3-proposal-links"><a href="/propuestas/?id=${encodeURIComponent(p.id)}">Leer propuesta ↗</a><a href="${gotoForm(p)}#formulario">Opinar sobre esta idea ↗</a></div></div></article>`;}

function proposalDeckV3(items){if(!items.length)return '<div class="no-results"><h3>Sin resultados para esos filtros.</h3><p>Prueba otra búsqueda o consulta las demás escuelas.</p></div>';return `<div class="v3-proposal-view" data-v3-carousel><div class="v3-carousel-top"><span>DESLIZA PARA EXPLORAR <span aria-hidden="true">↔</span></span><button class="v3-text-toggle" type="button" data-v3-list-toggle aria-pressed="false">Ver como lista</button></div><div class="v3-proposal-track" data-v3-track tabindex="0" role="region" aria-roledescription="carrusel" aria-label="Explorador de propuestas">${items.map(proposalPanelV3).join('')}</div><div class="v3-carousel-bottom"><button type="button" data-v3-prev aria-label="Propuesta anterior">← Anterior</button><output class="v3-carousel-counter" data-v3-counter aria-live="polite">01 / ${String(items.length).padStart(2,'0')}</output><button type="button" data-v3-next aria-label="Siguiente propuesta">Siguiente →</button></div></div>`;}

function proposalsListingV3(){return `${header()}<main id="main">${pageHero('AGENDA DE TRABAJO','PROPUESTAS PARA <em>EXPLORAR.</em>','Temas para conversar, documentar y revisar. Consejo de Facultad es la prioridad; Asamblea se consulta por separado.')}
<section class="section filters-section"><div class="container"><div class="filter-heading"><h2>Explora las líneas de trabajo</h2><span id="count-proposals" aria-live="polite"></span></div><div class="filter-controls"><div class="segmented" role="group" aria-label="Ámbito de representación"><button type="button" class="filter-scope active" data-scope="fiag">Consejo FIAG</button><button type="button" class="filter-scope" data-scope="asamblea">Asamblea</button><button type="button" class="filter-scope" data-scope="todos">Todas</button></div><div class="filter-extra"><label class="sr-only" for="school-filter">Filtrar escuela</label><select id="school-filter"><option value="todos">Todas las escuelas</option>${schools.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}<option value="comun">FIAG en conjunto</option></select><label class="sr-only" for="search-proposals">Buscar propuestas</label><input type="search" id="search-proposals" placeholder="Buscar por tema…"></div></div><div id="proposal-list" aria-live="off"></div><p class="disclaimer">Fichas en consulta. No representan acuerdos aprobados ni resultados ejecutados. Usa «Ver como lista» si prefieres explorar todos los títulos sin deslizar.</p></div></section>${banner('¿FALTA UN TEMA?','TU EXPERIENCIA TAMBIÉN CUENTA.','Describe una situación de tu escuela o propone una alternativa.','Compartir una idea')}</main>${footer()}`;}

function wireProposalCarouselV3(scope){const track=scope.querySelector('[data-v3-track]'),prev=scope.querySelector('[data-v3-prev]'),next=scope.querySelector('[data-v3-next]'),counter=scope.querySelector('[data-v3-counter]'),toggle=scope.querySelector('[data-v3-list-toggle]');if(!track)return;const slides=[...track.children];let current=0,listing=false;const update=()=>{if(!listing){const base=slides[0].offsetLeft;const left=track.scrollLeft;let closest=0,min=Infinity;slides.forEach((el,i)=>{const dist=Math.abs((el.offsetLeft-base)-left);if(dist<min){min=dist;closest=i;}});current=closest;}counter.textContent=`${String(current+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}`;prev.disabled=listing||current===0;next.disabled=listing||current===slides.length-1;};const move=delta=>{current=Math.max(0,Math.min(slides.length-1,current+delta));const base=slides[0].offsetLeft;track.scrollTo({left:slides[current].offsetLeft-base,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});update();};prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));track.addEventListener('scroll',()=>{if(!listing)update();},{passive:true});track.addEventListener('keydown',e=>{if(listing||e.target.closest('a,button,input'))return;if(e.key==='ArrowRight'){e.preventDefault();move(1);}if(e.key==='ArrowLeft'){e.preventDefault();move(-1);}});toggle.addEventListener('click',()=>{listing=!listing;scope.classList.toggle('is-list',listing);toggle.setAttribute('aria-pressed',String(listing));toggle.textContent=listing?'Ver carrusel':'Ver como lista';if(!listing){current=0;track.scrollLeft=0;}update();});update();}

function wireFiltersV3(){const target=$('#proposal-list');if(!target)return;const params=new URLSearchParams(location.search);let scope=params.get('ambito')||'fiag';let school=schools.some(s=>s.id===params.get('escuela'))||params.get('escuela')==='comun'?params.get('escuela'):'todos';let search='';if(!['fiag','asamblea','todos'].includes(scope))scope='fiag';if(school!=='todos'&&scope==='asamblea')scope='fiag';$('#school-filter').value=school;const repaint=()=>{$('.filter-scope').forEach(b=>{b.classList.toggle('active',b.dataset.scope===scope);b.setAttribute('aria-pressed',String(b.dataset.scope===scope));});const items=proposals.filter(p=>(scope==='todos'||p.scope===scope)&&(school==='todos'||p.school===school)&&(p.title+' '+p.summary+' '+p.area+' '+schoolName(p.school)).toLowerCase().includes(search));target.innerHTML=proposalDeckV3(items);const deck=target.querySelector('[data-v3-carousel]');if(deck)wireProposalCarouselV3(deck);$('#count-proposals').textContent=`${items.length} ${items.length===1?'tema':'temas'}`;$('#school-filter').disabled=scope==='asamblea';};$('.filter-scope').forEach(b=>b.addEventListener('click',()=>{scope=b.dataset.scope;if(scope==='asamblea')school='todos';$('#school-filter').value=school;repaint();}));$('#school-filter').addEventListener('change',e=>{school=e.target.value;repaint();});$('#search-proposals').addEventListener('input',e=>{search=e.target.value.trim().toLowerCase();repaint();});repaint();}

function teamPageV3(){const demo={name:'Integrante de ejemplo',role:'Rol por confirmar',school:'Escuela por confirmar',bio:'Ficha de demostración. Aquí colocaremos una presentación validada de cada integrante.',photo:'',isDemo:true};const people=team.length?team:[demo];return `${header()}<main id="main">${pageHero('LAS PERSONAS DETRÁS DE AURA','PERSONAS QUE <em>REPRESENTAN.</em>','Conoce las responsabilidades del equipo. Las fichas definitivas se publicarán con información autorizada.')}<section class="section v3-team-section"><div class="container"><div class="v3-section-lead"><div>${eyebrow('EQUIPO / FIAG')}<h2>UNA REPRESENTACIÓN<br><em>CON ROSTRO HUMANO.</em></h2></div><p>Queremos mostrar quiénes participan y qué función cumplen, respetando la autorización para difundir sus datos.</p></div><div class="v3-people">${people.map((t,i)=>`<article class="v3-person"><div class="v3-person-portrait">${t.photo?`<img loading="lazy" src="${esc(t.photo)}" alt="Retrato de ${esc(t.name)}">`:`<span class="v3-person-symbol" aria-hidden="true">✳</span><span class="v3-portrait-note">FOTOGRAFÍA POR CONFIRMAR</span>`}</div><div class="v3-person-caption">${t.isDemo?'<span class="v3-demo-warning">EJEMPLO VISUAL — NO ES INTEGRANTE CONFIRMADO</span>':''}<span class="v3-kicker">0${i+1} / ${esc(t.school)}</span><h3>${esc(t.name)}</h3><strong>${esc(t.role)}</strong><p>${esc(t.bio||'')}</p></div></article>`).join('')}</div><div class="v3-actions"><a class="btn btn-dark" href="/conocenos/">Conoce AURA ↗</a><a class="btn btn-mint" href="/participa/#formulario">Escríbenos ↓</a></div></div></section></main>${footer()}`;}

function resourcesPageV3(){return `${header()}<main id="main">${pageHero('FUENTES Y DOCUMENTOS','INFORMACIÓN PARA <em>CONSULTAR.</em>','Tres recursos principales. Desliza para descubrirlos o usa el modo lista para revisar todas las fuentes.') }<section class="section v3-resource-section"><div class="container"><div class="v3-resource-lead">${eyebrow('BIBLIOTECA / AURA')}<h2>DESLIZA, DESCUBRE<br><em>Y CONTRASTA.</em></h2><p>Enlaces a portales institucionales y normativa. Verifica su vigencia en las fuentes originales.</p></div><div class="v3-resource-widget" data-v3-resources><div class="v3-deck-head"><span>RECURSOS / ${String(resources.length).padStart(2,'0')}</span><button type="button" data-deck-toggle aria-pressed="false">Ver los tres como lista</button></div><div class="v3-deck-stack" data-deck-stack aria-roledescription="baraja de recursos">${resources.map((r,i)=>`<article class="v3-deck-card" data-deck-index="${i}" aria-label="Recurso ${i+1} de ${resources.length}"><div class="v3-deck-card-head"><span>0${i+1} / ${esc(r.type)}</span><span aria-hidden="true">↗</span></div><div class="v3-deck-glyph" aria-hidden="true">${['✳','◈','⌁'][i%3]}</div><h3>${esc(r.title)}</h3><p>${esc(r.detail)}</p><a href="${esc(r.href)}" target="_blank" rel="noopener noreferrer" class="v3-deck-link">Abrir fuente <span aria-hidden="true">↗</span></a></article>`).join('')}</div><div class="v3-deck-bottom"><button type="button" data-deck-prev>← Anterior</button><output aria-live="polite" data-deck-count>01 / ${String(resources.length).padStart(2,'0')}</output><button type="button" data-deck-next>Siguiente →</button></div><p class="v3-deck-help">En celular, desliza horizontalmente la tarjeta. No se elimina ningún recurso al hacerlo.</p></div><div class="v3-resource-outro"><h3>DOCUMENTOS DE AURA</h3><p>Publicaremos el plan de trabajo y documentos propios cuando sus versiones finales estén aprobadas y autorizadas.</p><a href="/participa/#formulario">¿Falta una fuente? Avísanos ↗</a></div></div></section></main>${footer()}`;}

function wireResourcesV3(){const widget=$('[data-v3-resources]');if(!widget)return;const cards=[...widget.querySelectorAll('[data-deck-index]')],prev=widget.querySelector('[data-deck-prev]'),next=widget.querySelector('[data-deck-next]'),output=widget.querySelector('[data-deck-count]'),toggle=widget.querySelector('[data-deck-toggle]');let index=0,listing=false;const update=()=>{cards.forEach((card,i)=>{const diff=i-index;card.dataset.depth=listing?'list':String(Math.max(-1,Math.min(diff,3)));const active=listing||diff===0;card.inert=!active;card.setAttribute('aria-hidden',String(!active));card.classList.toggle('is-active',diff===0);});prev.disabled=listing||index===0;next.disabled=listing||index===cards.length-1;output.textContent=`${String(index+1).padStart(2,'0')} / ${String(cards.length).padStart(2,'0')}`;};const move=delta=>{index=Math.max(0,Math.min(cards.length-1,index+delta));update();};prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));toggle.addEventListener('click',()=>{listing=!listing;widget.classList.toggle('is-list',listing);toggle.textContent=listing?'Ver como baraja':'Ver los tres como lista';toggle.setAttribute('aria-pressed',String(listing));update();});let start=null;const stack=widget.querySelector('[data-deck-stack]');stack.addEventListener('pointerdown',e=>{if(e.target.closest('a,button'))return;start={x:e.clientX,y:e.clientY};});stack.addEventListener('pointerup',e=>{if(!start||listing)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.25)move(dx<0?1:-1);});stack.addEventListener('pointercancel',()=>{start=null;});stack.addEventListener('keydown',e=>{if(listing||e.target.closest('a,button'))return;if(e.key==='ArrowLeft'){e.preventDefault();move(-1);}if(e.key==='ArrowRight'){e.preventDefault();move(1);}});update();}

function formPageV3(){let page=formPage();page=page.replace(/(<section class="page-hero[\s\S]*?<\/p>)(<\/div><\/section>)/,'$1<div class="v3-form-jump"><a class="btn btn-mint" href="#formulario" data-jump-form>Ir al formulario ↓</a><a class="v3-secondary-link" href="/propuestas/">Antes, explorar propuestas ↗</a></div>$2');return page.replace('<section class="section participatory-section">','<section class="section participatory-section" id="formulario" tabindex="-1" aria-label="Formulario de participación">');}

function wireParticipationV3(){const form=$('#idea-form'),target=$('#formulario');if(!form||!target)return;const query=new URLSearchParams(location.search);const desired=query.get('escuela');if(schools.some(s=>s.id===desired))$('#school').value=desired;const focus=()=>{target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});target.focus({preventScroll:true});};const trigger=$('[data-jump-form]');if(trigger)trigger.addEventListener('click',e=>{e.preventDefault();history.replaceState(null,'',location.pathname+location.search+'#formulario');focus();});if(location.hash==='#formulario')requestAnimationFrame(()=>focus());}

function trackingV3(){const counts=Object.keys(statuses).map(key=>({key,label:statuses[key].title,n:proposals.filter(p=>p.status===key).length}));return `${header()}<main id="main">${pageHero('TRANSPARENCIA','SEGUIMIENTO DE <em>INICIATIVAS.</em>','Diferenciamos temas en consulta de gestiones verificadas: no presentamos avances sin respaldo documental.',true)}<section class="section"><div class="container">${sectionIntro('ETAPAS DE TRABAJO','¿Cómo se registra <em>el avance?</em>','Los estados se asignan cuando exista evidencia suficiente.') }<div class="tracking-timeline">${Object.entries(statuses).map(([key,s],i)=>`<div class="tracking-step"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p></div><strong>${proposals.filter(p=>p.status===key).length} temas</strong></div>`).join('')}</div></div></section><section class="section section-track-data"><div class="container"><div class="track-note"><span class="notice-symbol">i</span><div><h3>Estado actual de la agenda</h3><p>Hay ${proposals.length} temas documentados como borradores: ${counts.map(x=>`${x.n} ${x.label.toLowerCase()}`).join('; ')}. Los estados no implican que exista una actuación institucional sin evidencia publicada.</p><a class="text-link" href="/propuestas/">Explorar temas ↗</a></div></div></div></section></main>${footer()}`;}

const pageMap={inicio:home,propuestas:()=>{const p=proposals.find(p=>p.id===new URLSearchParams(location.search).get('id'));return p?proposalDetail(p):proposalsListingV3();},fiag:fiagV3,escuela:schoolProfileV3,conocenos:about,asamblea:assembly,participa:formPageV3,equipo:teamPageV3,seguimiento:trackingV3,recursos:resourcesPageV3,privacidad:privacy,admin:adminPage};
const render = pageMap[route] || home;
const root=document.getElementById('app');
Promise.resolve(render()).then(markup=>{root.innerHTML=markup;wireNav();wireFiltersV3();wireForm();wireParticipationV3();wireResourcesV3();wireAdmin();});
